const ALPHABET_DATA = [
  {letter:'A', word:'Apple',    tip:'Make a fist with thumb resting on the side of the index finger.'},
  {letter:'B', word:'Ball',     tip:'Hold four fingers straight up together, thumb tucked across palm.'},
  {letter:'C', word:'Cat',      tip:'Curve all fingers and thumb to form a "C" shape.'},
  {letter:'D', word:'Dog',      tip:'Touch index finger to thumb forming a loop, other fingers up.'},
  {letter:'E', word:'Elephant', tip:'Curl all fingers down to touch the thumb — all four fingers folded.'},
  {letter:'F', word:'Fish',     tip:'Touch index fingertip to thumb tip; other three fingers spread up.'},
  {letter:'G', word:'Goat',     tip:'Index finger and thumb point horizontally to the side.'},
  {letter:'H', word:'Hat',      tip:'Index and middle fingers point horizontally together.'},
  {letter:'I', word:'Ice',      tip:'Raise only the pinky finger; others curled into a fist.'},
  {letter:'J', word:'Juice',    tip:'Like I, then trace a J arc in the air with your pinky.'},
  {letter:'K', word:'Kite',     tip:'Index finger up, middle finger angled, thumb between them.'},
  {letter:'L', word:'Lion',     tip:'Index finger points up, thumb points out — an "L" shape.'},
  {letter:'M', word:'Moon',     tip:'Tuck index, middle, and ring fingers over the thumb.'},
  {letter:'N', word:'Night',    tip:'Tuck index and middle fingers over the thumb.'},
  {letter:'O', word:'Ocean',    tip:'Curve all fingers to meet the thumb — forming an "O".'},
  {letter:'P', word:'Penguin',  tip:'Like K but pointed downward.'},
  {letter:'Q', word:'Queen',    tip:'Like G but pointed downward.'},
  {letter:'R', word:'Rainbow',  tip:'Cross index finger over middle finger.'},
  {letter:'S', word:'Sun',      tip:'Fist with thumb resting over the front of the fingers.'},
  {letter:'T', word:'Tiger',    tip:'Thumb tucked between index and middle fingers in a fist.'},
  {letter:'U', word:'Umbrella', tip:'Index and middle fingers together pointing up.'},
  {letter:'V', word:'Victory',  tip:'Index and middle fingers spread apart in a V shape.'},
  {letter:'W', word:'Water',    tip:'Index, middle, and ring fingers spread apart.'},
  {letter:'X', word:'X-Ray',    tip:'Curl the index finger into a hook shape.'},
  {letter:'Y', word:'Yellow',   tip:'Extend thumb and pinky; curl other three fingers.'},
  {letter:'Z', word:'Zebra',    tip:'Trace a Z in the air with your index finger.'},
  {letter:'SPACE', word:'Space',tip:'Form a fist with all fingers, including the thumb.'},
];

const VOWELS = new Set(['A','E','I','O','U']);

export function initLearnPage() {
  const grid        = document.getElementById('alphabetGrid');
  const modal       = document.getElementById('letterModal');
  const backdrop    = document.getElementById('modalBackdrop');
  const modalClose  = document.getElementById('modalClose');
  const searchInput = document.getElementById('learnSearch');
  const filterChips = document.querySelectorAll('.filter-chip');
  let currentFilter = 'all';

  // ── Build a single card ────────────────────────────────────
  function makeCard(entry) {
    const isSpace = entry.letter === 'SPACE';
    const isVowel = VOWELS.has(entry.letter);
    const card = document.createElement('div');
    card.className = `alpha-card${isVowel ? ' vowel' : ''}`;

    // For SPACE the card label uses a slightly smaller preset so it
    // never overflows — controlled by CSS clamp, but also guard here.
    card.innerHTML = `
      <div class="alpha-sign-icon">${HAND_SVGS[entry.letter] || ''}</div>
      <span class="alpha-letter">${entry.letter}</span>
      <span class="alpha-label">${entry.word}</span>
    `;
    card.addEventListener('click', () => openModal(entry));
    return card;
  }

  // ── Render grid ────────────────────────────────────────────
  function buildGrid(data) {
    grid.innerHTML = '';
    if (!data.length) {
      const msg = document.createElement('p');
      msg.style.cssText = 'color:var(--text-3);grid-column:1/-1;padding:20px 0;font-size:14px;';
      msg.textContent   = 'No letters found.';
      grid.appendChild(msg);
      return;
    }
    const frag = document.createDocumentFragment();
    data.forEach(entry => frag.appendChild(makeCard(entry)));
    grid.appendChild(frag);
  }

  // ── Filter helper ──────────────────────────────────────────
  function getFiltered() {
    let data = ALPHABET_DATA;
    const q  = (searchInput.value || '').trim().toUpperCase();
    if (q) data = data.filter(e => e.letter.startsWith(q) || e.word.toUpperCase().includes(q));
    if (currentFilter === 'vowels') data = data.filter(e => VOWELS.has(e.letter));
    return data;
  }

  // ── Search & filter events ─────────────────────────────────
  buildGrid(ALPHABET_DATA);
  searchInput.addEventListener('input', () => buildGrid(getFiltered()));
  filterChips.forEach(chip => chip.addEventListener('click', () => {
    filterChips.forEach(c => c.classList.remove('active'));
    chip.classList.add('active');
    currentFilter = chip.dataset.filter;
    buildGrid(getFiltered());
  }));

  // ── Modal ──────────────────────────────────────────────────
  function openModal(entry) {
    // Letter heading — for SPACE we render the word "SPACE" in full;
    // CSS clamp + word-break handle overflow on all screen sizes.
    document.getElementById('modalLetter').textContent = entry.letter;

    // Hand SVG
    document.getElementById('modalHandSvg').innerHTML = HAND_SVGS[entry.letter] || '';

    // Title: e.g.  "Letter A — "Apple""  or  "Sign: SPACE — "Space""
    const prefix = entry.letter === 'SPACE' ? 'Sign: SPACE' : `Letter ${entry.letter}`;
    document.getElementById('modalTitle').textContent = `${prefix} — "${entry.word}"`;

    // Description
    const desc = entry.letter === 'SPACE'
      ? 'In American Sign Language, the SPACE sign is used to indicate a word boundary in fingerspelling.'
      : `In American Sign Language, the letter "${entry.letter}" is represented by the hand shape shown above.`;
    document.getElementById('modalDesc').textContent = desc;

    // Tip
    document.getElementById('modalTip').innerHTML = `<strong>Tip:</strong> ${entry.tip}`;

    modal.style.display = 'flex';
    document.body.style.overflow = 'hidden';

    // Trap focus on the close button for accessibility
    setTimeout(() => modalClose.focus(), 60);
  }

  function closeModal() {
    modal.style.display       = 'none';
    document.body.style.overflow = '';
  }

  modalClose.addEventListener('click', closeModal);
  backdrop.addEventListener('click', closeModal);
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && modal.style.display !== 'none') closeModal();
  });
}
